add(){form('Add school',[['name','School name'],['city','City'],['person','Contact person'],['phone','WhatsApp number'],['au','School admin email (they log in with this)'],['fee','Monthly fee (Rs)','number'],['paidUntil','Paid until','date']],{fee:0,paidUntil:AD(TD(),30)},v=>{CRUN(()=>SVT({},{...v,status:'active'}))})},
