function ANIMN(){if(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)return;
const sel='.kp-n,.rvh-n,.rvh-t b,.dn-n,.dn2 li b,.sn,.stt b,.hero h2 b,.card .big,.g4 b';let k=0;
document.querySelectorAll(sel).forEach(el=>{const loc=el.closest('.rvh')?'en-IN':'en',delay=(k++)*70,tn=[];
const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;
while(n=w.nextNode()){if(n.parentNode.closest&&n.parentNode.closest('small,em'))continue;const m=/(-?)(\d[\d,]*)(\.\d+)?/.exec(n.nodeValue);if(!m)continue;const v=parseInt(m[2].replace(/,/g,''),10);if(!(v>0))continue;tn.push({n,t:n.nodeValue,pre:n.nodeValue.slice(0,m.index),sg:m[1],v,dc:m[3]||'',po:n.nodeValue.slice(m.index+m[0].length)})}
if(!tn.length)return;tn.forEach(o=>{o.n.nodeValue=o.pre+o.sg+'0'+o.dc+o.po});
const s0=performance.now()+delay,D=1200;(function f(t){const p=Math.max(0,Math.min(1,(t-s0)/D)),e=1-Math.pow(1-p,4);tn.forEach(o=>{o.n.nodeValue=p>=1?o.t:o.pre+o.sg+Math.round(o.v*e).toLocaleString(loc)+o.dc+o.po});if(p<1)requestAnimationFrame(f)})(performance.now())})}
