const CH={rvhm(v){RV.m=v;draw()},rvh(v,t){RV[t.dataset.k]=v;draw()},rule(v,t){S.rules[t.dataset.r]=t.checked;save()},tfa(v,t){S.set.tfa=t.checked?1:0;save()},ad(v){A.d=v||today();draw()},ac(v){A.c=v;draw()},pg(v){P.g=v;draw()},wt(v){W.aud=$('#wa-aud').value;W.no=$('#wa-no').value;W.tpl=v;W.text=TPL[v][1];draw()},perm(v,t){const a=S.roles[t.dataset.r],m=t.dataset.m,i=a.indexOf(m);if(t.checked&&i<0)a.push(m);if(!t.checked&&i>=0)a.splice(i,1);lg('Permission changed: '+t.dataset.r);save()}};
/* ===== Teacher: enter marks by roll no (roll nos are given by admin) ===== */
H.rmodal=function(){const c=rsCfg(),cls=[...new Set(CL.concat(S.students.map(s=>s.cls)))],subs=[...new Set(S.exams.map(e=>e.subject))],m=$('#md');m.hidden=false;
m.innerHTML=`<form class="mb" id="rmf"><h3>Enter marks by roll no</h3><p class="mu">Roll numbers are given by the admin. Choose the class, type the roll no and the marks. Marks go only to that child's Student and Parent portal.</p><label>Class<select name="cls">${cls.map(x=>`<option${c.cls==x?' selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Roll no<input name="roll" autocomplete="off" inputmode="numeric" required placeholder="e.g. 7"></label><div id="rmw" class="mu" style="margin:-4px 0 12px;min-height:20px"></div><label>Subject<input name="subject" list="rsub2" required value="${esc(c.subject)}" placeholder="e.g. Mathematics"><datalist id="rsub2">${subs.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label><label>Test<select name="test">${['Monthly test','Midterm','Final'].map(x=>`<option${c.test==x?' selected':''}>${x}</option>`).join('')}</select></label><label>Marks obtained<input name="marks" type="number" min="0" step="0.5" required></label><label>Total marks<input name="total" type="number" min="1" step="any" required value="${c.total}"></label><div class="ra"><button type="button" class="bt gh" data-a="close">Cancel</button><button type="button" class="bt gh" id="rmn">Save &amp; next</button><button class="bt">Save</button></div></form>`;
const f=m.querySelector('form'),E=f.elements,W=m.querySelector('#rmw');
const find=()=>{const r=E.roll.value.trim().toLowerCase();return r?S.students.find(s=>s.cls==E.cls.value&&s.status=='Active'&&String(s.roll||'').trim().toLowerCase()==r):null};
const look=()=>{const s=find(),r=E.roll.value.trim();if(!r){W.innerHTML='';return}if(!s){W.innerHTML='<span style="color:#dc2626">No active student with roll no '+esc(r)+' in '+esc(E.cls.value)+'</span>';return}const ex=S.exams.find(e=>rsKey(e)==rsKey({sid:s.id,subject:E.subject.value,test:E.test.value}));W.innerHTML='<b>'+esc(s.name)+'</b> &middot; Adm '+esc(s.adm)+(ex?' &middot; current marks '+ex.marks+'/'+ex.total+' (will be updated)':'')};
const go=next=>{if(!f.reportValidity())return;const s=find();if(!s){toast('Roll no not found in this class');return}const sub=E.subject.value.trim(),tot=+E.total.value,mk=+E.marks.value,test=E.test.value;if(!(tot>0)||isNaN(mk)||mk<0||mk>tot){toast('Marks must be between 0 and '+tot);return}
const key=rsKey({sid:s.id,subject:sub,test}),ex=S.exams.find(e=>rsKey(e)==key),by=(S.staff.find(x=>x.id==SES().id)||{}).name||'Admin',on=new Date().toLocaleDateString(),chg=!ex||ex.marks!=mk;
if(ex){ex.marks=mk;ex.total=tot;ex.by=by;ex.on=on}else S.exams.push({id:Math.max(0,...S.exams.map(e=>e.id))+1,sid:s.id,subject:sub,test,marks:mk,total:tot,by,on});
if(chg)sendMsg(s.id,'Result notification','Dear '+s.guardian+', '+s.name+(s.roll?' (Roll no '+s.roll+')':'')+' scored '+mk+'/'+tot+' in '+sub+' ('+test+'). Full result is in the Parent Portal.');
Object.assign(rsCfg(),{cls:E.cls.value,subject:sub,test,total:tot});lg('Marks saved: '+s.name+' '+sub);try{save()}catch(e){}toast(s.name+' (Roll '+s.roll+'): '+mk+'/'+tot+' saved');
if(next){E.roll.value='';E.marks.value='';W.innerHTML='';E.roll.focus();draw()}else{m.hidden=true;draw()}};
f.onsubmit=e=>{e.preventDefault();go(false)};m.querySelector('#rmn').onclick=()=>go(true);
['input','change'].forEach(ev=>f.addEventListener(ev,look));
E.roll.addEventListener('keydown',e=>{if(e.key=='Enter'){e.preventDefault();E.marks.focus()}});
E.marks.addEventListener('keydown',e=>{if(e.key=='Enter'){e.preventDefault();go(true)}});
setTimeout(()=>E.roll.focus(),50)};
{const _a=H.add;H.add=function(k){if(k=='exams')return H.rmodal();return _a.apply(this,arguments)}}

/* ===== Accountant portal ===== */
const ACN=[['adash','home','Accounts Dashboard','Collections, dues and expenses at a glance'],['acollect','fee','Collect Fee','Find a student by roll no, admission no or name'],['apays','fin','Payments & Daily Report','Every payment received, by date and mode'],['adef','par','Defaulters','Overdue fees and parent reminders']];
const ACS={q:'',c:''},APS={from:'',to:'',mode:''},ADS={c:''};
const pfe=p=>S.fees.find(f=>f.id==p.fid),pst=p=>{const f=pfe(p);return f?S.students.find(s=>s.id==f.sid):null},
byMode=L=>{const m={};L.forEach(p=>m[p.mode]=(m[p.mode]||0)+p.amt);return m},
modeBars=L=>{const m=byMode(L),t=sum(L,p=>p.amt);return Object.entries(m).map(([k,v])=>`<div class="mu" style="margin:0">${esc(k)}: <b>${money(v)}</b></div><div class="pb"><div style="width:${t?v/t*100:0}%"></div></div>`).join('')||'<p class="em">No payments in this period.</p>'},
payLine=p=>{const s=pst(p);return`<div class="cb"><span>${esc(s?s.name:'Unknown')}</span><span class="mu" style="margin:0 0 0 auto">${esc(p.date)} &middot; ${esc(p.mode)}</span><b>${money(p.amt)}</b></div>`};
function adash(){const F=fin(),td=today(),P=S.pays,tp=P.filter(p=>p.date==td),col=sum(tp,p=>p.amt),pm=P.filter(p=>p.date.slice(0,7)==mm()),u=S.staff.find(x=>x.id==SES().id)||{name:'Accountant'},
dl=act().map(s=>({s,b:sum(S.fees.filter(f=>f.sid==s.id&&fst(f)=='Overdue'),bal)})).filter(x=>x.b>0).sort((a,b)=>b.b-a.b).slice(0,6),
cp=CL.map(c=>[c,sum(S.students.filter(s=>s.cls==c),s=>owed(s.id))]),mx=Math.max(1,...cp.map(x=>x[1]));
return`<div class="hero"><div><h2>Welcome, ${esc(u.name)}</h2><p>Accounts - ${esc(S.set.name)}. Collections, dues and expenses in one place.</p></div><div><a class="bt" href="#acollect">Collect fee</a><a class="bt" href="#adef">Defaulters</a><a class="bt" href="#finance">Add expense</a><a class="bt" href="#payroll">Payroll</a></div></div>
<div class="g4">${stat('fee','Collected today',money(col),tp.length+' payments today','c-g')}${stat('fin','Collected this month',money(F.revM),'Net '+money(F.revM-F.eM),'c-b')}${stat('adm','Pending fees',money(F.pend),S.fees.filter(f=>bal(f)>0).length+' open challans','c-r')}${stat('pay','Expenses this month',money(F.eM),'Bills, rent and salaries','c-r')}</div>
<div class="two"><div class="card"><div class="tb"><h3>Recent payments</h3><a class="bt sm gh" href="#apays" style="margin-left:auto">All payments</a></div>${P.slice(-8).reverse().map(payLine).join('')||'<p class="em">No payments yet.</p>'}</div><div class="card"><div class="tb"><h3>Overdue - highest balance</h3><a class="bt sm gh" href="#adef" style="margin-left:auto">See all</a></div>${dl.map(x=>`<div class="cb"><span>${esc(x.s.name)} <span class="mu">${esc(x.s.cls)}</span></span><b style="margin-left:auto">${money(x.b)}</b><button class="bt sm" data-a="rem" data-id="${x.s.id}">Remind</button></div>`).join('')||'<p class="em">No overdue fees.</p>'}</div></div>
<div class="two"><div class="card"><h3>Collection by payment mode (this month)</h3>${modeBars(pm)}</div><div class="card"><h3>Pending fees by class</h3>${cp.map(x=>`<div class="mu" style="margin:0">${esc(x[0])}: <b>${money(x[1])}</b></div><div class="pb"><div style="width:${x[1]/mx*100}%"></div></div>`).join('')}</div></div>`}
function acRes(){const q=ACS.q.trim().toLowerCase(),c=ACS.c;if(!q&&!c)return'<p class="em">Type a roll no, admission no, name or phone - or pick a class.</p>';
let L=S.students.filter(s=>s.status=='Active'&&(!c||s.cls==c)&&(!q||[s.roll,s.adm,s.name,s.guardian,s.phone].join(' ').toLowerCase().indexOf(q)>-1)).sort((a,b)=>(parseInt(a.roll)||9999)-(parseInt(b.roll)||9999)||String(a.name).localeCompare(b.name));const tot=L.length;L=L.slice(0,25);if(!L.length)return'<p class="em">No student found.</p>';
return L.map(s=>{const fs=S.fees.filter(f=>f.sid==s.id).slice().reverse();return`<div class="card" style="margin-bottom:12px"><div class="tb"><h3>${esc(s.name)} <span class="mu">Roll ${esc(s.roll||'-')} &middot; ${esc(s.cls)} &middot; ${esc(s.adm)}</span></h3><button class="bt sm blue" data-a="acnew" data-id="${s.id}" style="margin-left:auto">New challan</button></div><div class="mu">Guardian: ${esc(s.guardian)} &middot; ${esc(s.phone)} &middot; Total due: <b>${money(owed(s.id))}</b></div>${fs.map(f=>`<div class="cb"><span>${esc(f.month)}</span><span class="mu" style="margin:0 0 0 auto">Due ${esc(f.due)} &middot; Paid ${money(f.paid)} of ${money(f.amount)}</span>${badge(fst(f))}${bal(f)>0?`<button class="bt sm" data-a="col" data-k="fees" data-id="${f.id}">Collect</button>`:''}${f.paid>0?`<button class="bt sm gh" data-a="rec" data-k="fees" data-id="${f.id}">Receipt</button>`:''}</div>`).join('')||'<p class="em">No challans yet.</p>'}</div>`}).join('')+(tot>25?`<p class="mu">Showing 25 of ${tot}. Type more to narrow down.</p>`:'')}
function acollect(){return`<div class="card" style="margin-bottom:14px"><h3>Find student</h3><div style="display:flex;gap:8px;flex-wrap:wrap"><select data-acc="1"><option value="">All classes</option>${CL.map(c=>`<option${ACS.c==c?' selected':''}>${c}</option>`).join('')}</select><input id="acq" data-acq="1" placeholder="Roll no / adm no / name / phone" value="${esc(ACS.q)}" style="min-width:250px"></div></div><div id="acr">${acRes()}</div>`}
function apRange(){const f=APS.from||today().slice(0,8)+'01',t=APS.to||today();return{f,t,L:S.pays.filter(p=>p.date>=f&&p.date<=t&&(!APS.mode||p.mode==APS.mode)).slice().sort((a,b)=>b.date.localeCompare(a.date))}}
function apRows(L){return L.map(p=>{const s=pst(p),f=pfe(p);return[p.date,p.rn||'-',s?s.name:'Unknown',s?(s.roll||''):'',s?s.cls:'',f?f.month:'',p.mode,p.by||'',p.amt]})}
function apays(){const r=apRange(),tot=sum(r.L,p=>p.amt),bm=byMode(r.L);
return`<div class="card" style="margin-bottom:14px"><div class="tb" style="flex-wrap:wrap;gap:10px"><label style="margin:0">From<input type="date" data-ap="from" value="${r.f}"></label><label style="margin:0">To<input type="date" data-ap="to" value="${r.t}"></label><label style="margin:0">Mode<select data-ap="mode"><option value="">All</option>${['Cash','Bank','Online'].map(m=>`<option${APS.mode==m?' selected':''}>${m}</option>`).join('')}</select></label><button class="bt blue" data-a="apprn" style="margin-left:auto">Print report</button><button class="bt gh" data-a="apcsv">Download CSV</button></div></div>
<div class="g4">${stat('fin','Total received',money(tot),r.L.length+' payments','c-g')}${stat('fee','Cash',money(bm.Cash||0),'Selected period','c-b')}${stat('pay','Bank',money(bm.Bank||0),'Selected period','c-b')}${stat('adm','Online',money(bm.Online||0),'Selected period','c-b')}</div>
<div class="card" style="margin-top:18px"><h3>Payments</h3><div class="tw"><table><thead><tr><th>Date</th><th>Receipt</th><th>Student</th><th>Roll</th><th>Class</th><th>Fee</th><th>Mode</th><th>Received by</th><th>Amount</th></tr></thead><tbody>${apRows(r.L).map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td><td>${esc(x[2])}</td><td>${esc(x[3])}</td><td>${esc(x[4])}</td><td>${esc(x[5])}</td><td>${esc(x[6])}</td><td>${esc(x[7])}</td><td><b>${money(x[8])}</b></td></tr>`).join('')||'<tr><td colspan="9" class="em">No payments in this period.</td></tr>'}</tbody></table></div></div>`}
function adef(){const c=ADS.c,L=act().filter(s=>!c||s.cls==c).map(s=>{const o=S.fees.filter(f=>f.sid==s.id&&fst(f)=='Overdue');return{s,o,b:sum(o,bal),d:o.length?Math.max(...o.map(f=>Math.floor((Date.now()-Date.parse(f.due))/864e5))):0}}).filter(x=>x.o.length).sort((a,b)=>b.b-a.b);
return`<div class="card" style="margin-bottom:14px"><div class="tb" style="flex-wrap:wrap;gap:10px"><select data-adc="1"><option value="">All classes</option>${CL.map(x=>`<option${c==x?' selected':''}>${x}</option>`).join('')}</select><span class="mu" style="margin:0">${L.length} students &middot; overdue <b>${money(sum(L,x=>x.b))}</b></span><button class="bt" data-a="wrun" style="margin-left:auto">Queue reminders for all</button></div><p class="mu">Queued reminders appear on the WhatsApp page, where each one is sent with one tap.</p></div>
<div class="card"><div class="tw"><table><thead><tr><th>Roll</th><th>Student</th><th>Class</th><th>Guardian</th><th>WhatsApp</th><th>Challans</th><th>Days late</th><th>Overdue</th><th></th></tr></thead><tbody>${L.map(x=>`<tr><td>${esc(x.s.roll||'')}</td><td>${esc(x.s.name)}</td><td>${esc(x.s.cls)}</td><td>${esc(x.s.guardian)}</td><td>${esc(x.s.phone)}</td><td>${x.o.length}</td><td>${x.d}</td><td><b>${money(x.b)}</b></td><td class="ac"><button class="bt sm" data-a="col" data-k="fees" data-id="${x.o[0].id}">Collect</button><button class="bt sm blue" data-a="rem" data-id="${x.s.id}">Remind</button></td></tr>`).join('')||'<tr><td colspan="9" class="em">No overdue fees. Well done!</td></tr>'}</tbody></table></div></div>`}
Object.assign(PG,{adash,acollect,apays,adef});
Object.assign(H,{rem(k,id){const s=S.students.find(x=>x.id==id);if(!s)return;sendMsg(s.id,'Fee reminder',fill(TPL.fee[1],s));const m=S.msgs[0];if(m.st=='Invalid number'){toast('Check the parent WhatsApp number');save();draw();return}openWa(m);lg('Fee reminder: '+s.name);save();toast('Opening WhatsApp');draw()},
acnew(k,id){const s=S.students.find(x=>x.id==id);if(!s)return;form('New challan - '+esc(s.name),[['month','Fee type / month'],['amount','Amount (Rs)','number'],['due','Due date','date']],{month:mon(),amount:+S.struct[s.cls]||0,due:today().slice(0,8)+String(S.set.dueDay).padStart(2,'0')},v=>{S.fees.push({id:uid(),sid:s.id,month:v.month,due:v.due,amount:v.amount,paid:0});lg('Challan created: '+s.name);toast('Challan created')})},
apcsv(){const r=apRange(),q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"',csv=['Date,Receipt,Student,Roll,Class,Fee,Mode,Received by,Amount'].concat(apRows(r.L).map(x=>x.map(q).join(','))).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='payments-'+r.f+'-to-'+r.t+'.csv';document.body.appendChild(a);a.click();a.remove()},
apprn(){const r=apRange(),w=window.open('','_blank');if(!w){toast('Allow pop-ups to print');return}const bm=byMode(r.L);w.document.write('<title>Payment report</title><style>body{font:13px Arial;margin:18px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:5px;text-align:left}</style><h2>'+esc(S.set.name)+' - Payment report</h2><p>'+esc(r.f)+' to '+esc(r.t)+(APS.mode?' ('+esc(APS.mode)+')':'')+'<br>Total received: <b>'+money(sum(r.L,p=>p.amt))+'</b> &middot; '+Object.entries(bm).map(e=>e[0]+' '+money(e[1])).join(' &middot; ')+'</p><table><tr><th>Date</th><th>Receipt</th><th>Student</th><th>Roll</th><th>Class</th><th>Fee</th><th>Mode</th><th>By</th><th>Amount</th></tr>'+apRows(r.L).map(x=>'<tr>'+x.map((v,i)=>'<td>'+(i==8?money(v):esc(v))+'</td>').join('')+'</tr>').join('')+'</table><script>setTimeout(function(){print()},300)<\/script>');w.document.close()}});
document.addEventListener('input',e=>{const x=e.target;if(!x.dataset||!x.dataset.acq)return;ACS.q=x.value;const r=document.getElementById('acr');if(r)r.innerHTML=acRes()});
