document.addEventListener('submit',e=>{if(e.target.id!='lf')return;e.preventDefault();const f=new FormData(e.target),r=e.target.dataset.r,u=String(f.get('u')).trim(),pw=String(f.get('p'));if(!LOC){CLOGIN(r,u,pw,false);return}const k=auth(r,u,pw);if(!k){$('#er').textContent='Wrong username or password. Please try again.';return}
setSES(k);S.logins.unshift({r:PORT[r][0]+': '+k.name,t:new Date().toLocaleString()});S.logins=S.logins.slice(0,10);save();$('#v').classList.add('fx');location.hash='#'+nav(k)[0][0];draw();setTimeout(()=>$('#v').classList.remove('fx'),1900)});
document.addEventListener('change',e=>{const t=e.target,c=t.dataset.c;if(c&&CH[c])CH[c](t.value,t)});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.c=='q'){Q[t.dataset.k]=t.value;$('#tb').innerHTML=rowsHtml(t.dataset.k)}});
addEventListener('hashchange',()=>{$('#sb').classList.remove('open');$('#v').classList.add('fx');draw();scrollTo(0,0);clearTimeout(window.ft);window.ft=setTimeout(()=>$('#v').classList.remove('fx'),1900)});

/* ===== ESMOS timetable v2: dates, period timings, add/edit, send to teachers/students/parents ===== */
const TTS=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),
TTD=s=>new Date(s+'T00:00:00'),
TTA=(s,n)=>{const x=TTD(s);x.setDate(x.getDate()+n);return TTS(x)},
TTM=s=>{const x=TTD(s);x.setDate(x.getDate()-(x.getDay()+6)%7);return TTS(x)},
TTF=s=>TTD(s).toLocaleDateString('en',{day:'numeric',month:'short'}),
TTY=s=>TTD(s).toLocaleDateString('en',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),
TT12=t=>{const a=String(t||'08:00').split(':'),h=+a[0],m=a[1]||'00';return (h%12||12)+':'+m+' '+(h>=12?'PM':'AM')},
TTW=()=>{if(!FL.ttw){const n=new Date();if(n.getDay()==0)n.setDate(n.getDate()+1);FL.ttw=TTM(TTS(n))}return FL.ttw},
TTP=()=>S.ttp||(S.ttp=[['08:00','08:40'],['08:40','09:20'],['09:20','10:00'],['10:30','11:10'],['11:10','11:50'],['11:50','12:30'],['12:30','13:10'],['13:10','13:50']]),
TTB=()=>S.ttb||(S.ttb=['10:00','10:30']),
TTAUD={staff:'Teachers',students:'Students',parents:'Parents'};
function ttBar(ro){const W=TTW(),u=SES(),p=S.ttpub,vis=p&&((u.role=='employee'&&(p.aud||[]).includes('staff'))||((u.role=='student'||u.role=='parent')&&(p.cls=='All'||anMyCls(u).includes(p.cls))));
return`<div class="card ttbar"><div class="tb"><button class="bt gh sm" data-a="ttprev">&lsaquo; Prev</button><input type="date" data-c="ttw" value="${W}"><button class="bt gh sm" data-a="ttnext">Next &rsaquo;</button><button class="bt sm" data-a="tttoday">This week</button><span class="mu" style="margin:0 0 0 auto">Week: ${TTF(W)} - ${TTF(TTA(W,5))}</span></div>${vis?`<div class="ttpb">${ic('ann')}<div><b>Timetable updated</b> on ${esc(p.on)}. Effective from <b>${TTF(p.from)}</b>.${p.note?'<br>'+esc(p.note):''}</div></div>`:''}</div>`}
function ttHead(){const p=S.ttpub;return`<div class="card ttbar"><div class="tb" style="flex-wrap:wrap;gap:8px"><button class="bt gh sm" data-a="ttprev">&lsaquo; Prev</button><input type="date" data-c="ttw" value="${TTW()}"><button class="bt gh sm" data-a="ttnext">Next &rsaquo;</button><button class="bt gh sm" data-a="tttoday">This week</button><select data-c="ttc"><option value="All">All classes</option>${CL.map(c=>`<option${FL.ttc==c?' selected':''}>${c}</option>`).join('')}</select></div><div class="tb" style="flex-wrap:wrap;gap:8px;margin-top:10px"><button class="bt" data-a="ttadd">+ Add period</button><button class="bt blue" data-a="ttsend">Send timetable</button><button class="bt gh" data-a="ttper">Period timings</button><button class="bt gh" data-a="ttprn">Print</button></div><p class="mu" style="margin:10px 0 0">Week of ${TTY(TTW())}. ${p?'Last sent '+esc(p.on)+' (effective '+TTF(p.from)+').':'Not sent to teachers and students yet.'}</p></div>`}
