function side(){const sb=document.getElementById('sb');if(!sb||!sess().role)return;const on=location.hash=='#hubs';let a=sb.querySelector('a[href="#hubs"]');if(!a){a=document.createElement('a');a.href='#hubs';a.innerHTML=SV(P.apps,' class="i" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"')+'Hubs';const lo=sb.querySelector('.lo');lo?sb.insertBefore(a,lo):sb.appendChild(a)}if(on)sb.querySelectorAll('a.on').forEach(x=>x.classList.remove('on'));a.classList.toggle('on',on)}
