if(typeof PLAT=='function'){const _p=PLAT;PLAT=function(ho){const h=typeof ho=='string'?ho:location.hash.slice(1);if(h=='hubs'&&!sess().role){const p=document.getElementById('pl');if(p){p.hidden=false;p.innerHTML='<div style="padding:22px 16px 0;font-family:Inter,system-ui,sans-serif;color:#0f1d3a"><div class="hb-top" style="margin-bottom:0"><div><h2 style="font-size:24px">Hubs</h2><p>Apps, help and information</p></div></div></div><div id="hbh" style="padding:12px 16px 0"></div>'+(typeof HBAR=='function'?HBAR():'');V=NX||'home';NX=null;mount(document.getElementById('hbh'));window.scrollTo(0,0);return}}const r=_p.apply(this,arguments);fix();return r}}
if(typeof draw=='function'){const _d=draw;draw=function(){const r=_d.apply(this,arguments);try{if(sess().role){side();if(location.hash=='#hubs'&&document.getElementById('v')){V='home';mount()}}}catch(e){}return r}}
