/* WhatsApp feature icon: same gradient tile + white glyph as the other feature icons */
(function(){
function sym(){var sp=document.querySelector('#sp svg');if(!sp)return false;if(document.getElementById('i-waw'))return true;var w=document.getElementById('i-wai');if(!w)return false;sp.insertAdjacentHTML('beforeend','<symbol id="i-waw" viewBox="0 0 24 24">'+w.innerHTML.replace(/fill="#25D366"/i,'fill="currentColor"')+'</symbol>');return true}
function fix(){try{if(!sym())return;document.querySelectorAll('.mkl .ic2 use,.mkv .ic2 use,.mkgd .ic2 use').forEach(function(u){if(u.getAttribute('href')==='#i-wai')u.setAttribute('href','#i-waw')})}catch(e){}}
var t=0;function sched(){if(t)return;t=requestAnimationFrame(function(){t=0;fix()})}
if(document.body){new MutationObserver(sched).observe(document.body,{childList:true,subtree:true});fix()}
})();

/* Phone mockup screens scroll by themselves (down, pause, back up). Pauses while the visitor touches or hovers the phone. */
(function(){
if(window.__mkAuto)return;window.__mkAuto=1;
var SPEED=34,HOLD=1300,st=new WeakMap(),now=function(){return performance.now()};
var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches;
function pause(e,ms){var el=e.target&&e.target.closest&&e.target.closest('.mkv');if(!el)return;var s=st.get(el);if(s){s.user=now()+ms;s.sync=1}}
['wheel','touchstart','touchmove','pointerdown','keydown'].forEach(function(n){document.addEventListener(n,function(e){pause(e,4500)},{passive:true,capture:true})});
document.addEventListener('pointerover',function(e){if(e.pointerType==='mouse')pause(e,1200)},{passive:true,capture:true});
document.addEventListener('pointermove',function(e){if(e.pointerType==='mouse')pause(e,1200)},{passive:true,capture:true});
function tick(ts){
  try{
    document.querySelectorAll('.mkv.on').forEach(function(el){
      var max=el.scrollHeight-el.clientHeight;if(max<8)return;
      var s=st.get(el);
      if(!s){s={y:0,dir:1,wait:HOLD,last:ts,seen:ts,user:0,sync:0};st.set(el,s)}
      if(ts-s.seen>250){s.y=0;s.dir=1;s.wait=HOLD;el.scrollTop=0;s.sync=0}
      s.seen=ts;var dt=Math.min(64,ts-s.last);s.last=ts;
      if(now()<s.user)return;
      if(s.sync){s.y=el.scrollTop;s.sync=0;s.wait=Math.max(s.wait,600)}
      if(s.wait>0){s.wait-=dt;return}
      s.y+=s.dir*SPEED*dt/1000;
      if(s.y>=max){s.y=max;s.dir=-1;s.wait=HOLD}else if(s.y<=0){s.y=0;s.dir=1;s.wait=HOLD}
      el.scrollTop=s.y;
    });
  }catch(x){}
  requestAnimationFrame(tick);
}
if(!reduce)requestAnimationFrame(tick);
})();

/* ===================== Back buttons everywhere (added) ===================== */
(function(){
if(window.__BACKFIX)return;window.__BACKFIX=1;
const BKI='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>';
const sess=()=>{try{return typeof SES=='function'?SES():{}}catch(e){return{}}};
const navL=()=>{try{const u=sess();return u.role?nav(u):[]}catch(e){return[]}};
const home=()=>{const L=navL();return L.length?L[0][0]:''};
let PREV='',CUR=location.hash;
addEventListener('hashchange',()=>{PREV=CUR;CUR=location.hash});

/* 1) Signed-in app: back button in the top bar on every page except the home page */
function appBack(){
  const top=document.querySelector('main>.top');if(!top||!sess().role)return;
  let b=document.getElementById('appbk');
  if(!b){
    b=document.createElement('button');b.id='appbk';b.type='button';b.className='hb-bk';
    b.setAttribute('aria-label','Back');b.innerHTML=BKI;top.insertBefore(b,top.firstChild);
    b.addEventListener('click',()=>{
      const id=PREV.slice(1),ok=id&&id!=location.hash.slice(1)&&(id=='hubs'||navL().some(x=>x[0]==id));
      location.hash='#'+(ok?id:home());
    });
  }
  const cur=location.hash.slice(1)||home();
  const inHubSub=!!document.querySelector('#v .hb-top');
  b.style.display=(cur==home()||inHubSub)?'none':'';
}
if(typeof draw=='function'){const _d=draw;draw=function(){const r=_d.apply(this,arguments);try{appBack()}catch(e){}return r}}

/* 2) Public Hubs screen: back to Home */
function hubsBack(){
  const hd=document.querySelector('#pl > div > .hb-top');if(!hd||sess().role)return;
  let b=document.getElementById('hbhb');
  if(!b){
    b=document.createElement('button');b.id='hbhb';b.type='button';b.className='hb-bk';
    b.setAttribute('aria-label','Back to Home');b.innerHTML=BKI;
    b.addEventListener('click',()=>{GO('')});
    hd.insertBefore(b,hd.firstChild);
  }
  b.style.display=document.querySelector('#hbh .hb-top')?'none':'';
}
if(typeof PLAT=='function'){const _p=PLAT;PLAT=function(ho){const r=_p.apply(this,arguments);try{if((typeof ho=='string'?ho:location.hash.slice(1))=='hubs')hubsBack()}catch(e){}return r}}

/* keep both buttons in sync when moving between Hubs sections */
document.addEventListener('click',e=>{
  if(!(e.target.closest&&e.target.closest('[data-hb]')))return;
  try{hubsBack();appBack()}catch(x){}
});

/* 3) Role login form (admin / employee / parent / student): back to all portals */
if(typeof lgin=='function'){const _l=lgin;lgin=function(){const r=_l.apply(this,arguments);try{
  const d=document.getElementById('lgn');
  if(d&&document.getElementById('lf')&&!document.getElementById('lgbk')){
    const a=document.createElement('a');a.id='lgbk';a.className='lgb';a.href='#login';a.innerHTML='&#8249; Back';
    d.insertBefore(a,d.firstChild);
  }
}catch(e){}return r}}
})();

;(function(){let q=0;const run=()=>{q=0;try{document.querySelectorAll('td.ac').forEach(td=>{const n=td.querySelectorAll(':scope>.bt').length,ib=!!td.querySelector(':scope>.ib');td.classList.toggle('ac4',n>=4&&!ib)});document.querySelectorAll('[data-a="lpg"]').forEach(b=>{const p=b.parentNode;if(p&&!p.classList.contains('pgr'))p.classList.add('pgr')})}catch(e){}};new MutationObserver(()=>{if(!q)q=requestAnimationFrame(run)}).observe(document.documentElement,{childList:true,subtree:true});run()})();
